def nominatim(q):
    try:
        r = get("https://nominatim.openstreetmap.org/search", {"q": q, "limit": 1, "countrycodes": "jp"})
    except Exception as e:
        print("ERR", q, e); r = None
    time.sleep(1.2)
    return (round(float(r[0]["lat"]), 6), round(float(r[0]["lon"]), 6)) if r else None


def main():
    hubs_js = (ROOT / "data" / "hubs.js").read_text(encoding="utf-8")
    hub_ll = {h: (float(a), float(b)) for h, a, b in re.findall(r'id: "(\w+)",[^}]*?lat: ([\d.]+), lng: ([\d.]+)', hubs_js)}
    hub_ll["chitose"] = (42.7752, 141.6923)  # ร้านในสนามบินใช้พิกัดสนามบิน
    old = {}
    if OUT.exists() and "window.FOODS = [" in OUT.read_text(encoding="utf-8"):
        try: old = {f["ja"]: f for f in json.loads(OUT.read_text(encoding="utf-8").split("window.FOODS = ", 1)[1].rstrip().rstrip(";"))}
        except ValueError: old = {}
    out = []
    for i, (hub, area, name, en, ja, cuisine, sig, price, hours, closed, queue, pay, tags, q) in enumerate(F, 1):
        f = dict(id=f"f{i}", hub=hub, area=area, name=name, en=en, ja=ja, cuisine=cuisine, signature=sig, price=price, open=hours, closedDays=closed,
                 queue=queue, pay=pay, tags=tags, hours=1, dur="1 ชม.", checked="2026-11")
        o = old.get(ja)
        if o and o.get("lat"):
            f["lat"], f["lng"], f["acc"] = o["lat"], o["lng"], o.get("acc", "")
        else:
            ll = nominatim(q) or nominatim(ja)
            h = hub_ll[hub]
            if ll and abs(ll[0] - h[0]) < 0.8 and abs(ll[1] - h[1]) < 1.0:
                f["lat"], f["lng"], f["acc"] = ll[0], ll[1], "จาก OpenStreetMap"
            else:
                f["lat"], f["lng"], f["acc"] = h[0], h[1], "ประมาณ (กลางเมือง)"
        print(f["id"], ja, f["lat"], f["lng"], f["acc"])
        out.append(f)
    OUT.write_text("// ร้านอาหาร — สร้างด้วย tools/build_foods.py (พิกัดจาก OpenStreetMap/Nominatim) แก้ต่อได้\n"
                   "// open = เวลาเปิด (ข้อความ), hours = เวลาที่ใช้ในแผน (ชม.), price = [ต่ำ, สูง] เยนต่อคน — ตรวจ พ.ย. 2026 เป็นค่าประมาณ\n"
                   "window.FOODS = " + json.dumps(out, ensure_ascii=False, indent=1) + ";\n", encoding="utf-8")
    print("total", len(out), "approx", sum(1 for f in out if f["acc"].startswith("ประมาณ")))


if __name__ == "__main__":
    main()
